/** One row per channel. */
export const channelSettings = defineTable(
  'channel_settings',
  { module: 'M37', scope: 'org' },
  {
    ...baseColumns,
    channel: enumText(channelSettingChannels).notNull(),
    isEnabled: boolean().notNull().default(false),
    /** required to enable an outside channel */
    connectionId: uuid().references((): AnyPgColumn => integrationConnections.id),
    /** the WhatsApp number, SMS sender name or from-address */
    sender: text(),
    ratePerMinute: integer().notNull().default(60),
    quietFrom: timeStr().notNull().default('21:00'),
    quietTo: timeStr().notNull().default('08:00'),
    /** for `sms` and `whatsapp`, kept in step with the ledger */
    creditBalance: paisa().notNull().default(0),
    lowCreditAlert: paisa().notNull().default(0),
  },
  (t) => [
    nonNegative('channel_settings', t.creditBalance),
    nonNegative('channel_settings', t.lowCreditAlert),
    uniqueIndex('channel_settings_channel_uq').on(t.orgId, t.channel).where(live(t)),
  ],
);

