/** A bulk message composed by staff. */
export const messageCampaigns = defineTable(
  'message_campaigns',
  { module: 'M37', scope: 'org' },
  {
    ...baseColumns,
    /** internal name */
    title: text().notNull(),
    /** the sender must have access to each */
    branchIds: uuid().array().notNull(),
    /** in order of preference */
    channels: text().array().notNull(),
    /** at least one language is required */
    bodyEn: text(),
    bodyUr: text(),
    /** required when WhatsApp is a channel */
    whatsappTemplateId: uuid().references((): AnyPgColumn => whatsappTemplates.id, {
      name: 'message_campaigns_whatsapp_template_id_whatsapp_templa_e1aae467',
    }),
    /** `{ kind: guardians \ | staff \ | students, gradeIds?, sectionIds?, routeIds?, roleKeys?, filter?: defaulters \ | absent_today \ | boarders, userIds? }` */
    audience: jsonb().notNull(),
    isUrgent: boolean().notNull().default(false),
    /** empty means on approval */
    sendAt: timestamptz(),
    status: enumText(messageCampaignStatuses).notNull().default('draft'),
    recipientCount: integer().notNull().default(0),
    estimatedCost: paisa().notNull().default(0),
    actualCost: paisa().notNull().default(0),
    /** by status */
    counts: jsonb().notNull().default({}),
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    createdBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [
    check(
      'message_campaigns_body_en_some',
      sql`${t.bodyEn} is not null or ${t.bodyUr} is not null`,
    ),
    check(
      'message_campaigns_whatsapp_template_id_needed',
      sql`not ('whatsapp' = any (${t.channels})) or ${t.whatsappTemplateId} is not null`,
    ),
    nonNegative('message_campaigns', t.estimatedCost),
    nonNegative('message_campaigns', t.actualCost),
  ],
);

